"""Render a self-contained local listening room from the private sample manifest."""
from pathlib import Path
import html,json
ROOT=Path(__file__).resolve().parent.parent
DIR=ROOT/'demos/three-hosts-2026-09-17'
h=html.escape
bios={
'mira':('The quiet wonder of it all.','Mira finds the human-scale detail inside an enormous universe. Calm, curious and quietly funny, she follows how we know—not just what we found.','#c9cdf6','SPACE & PHYSICS'),
'clara':('There’s always more going on.','Clara notices the unexpected inside an ordinary moment. Warm and gently amused, she follows living things on their own terms.','#c7dcae','WILDLIFE & NATURE'),
'elias':('Let’s keep asking how.','Elias takes familiar experiences apart to find the mechanism. Precise, playful, and careful to keep a conclusion within its experiment.','#f1c6aa','MINDS & MECHANISMS')}
d=json.loads((DIR/'manifest.json').read_text());cards=[]
for number,e in enumerate(d['episodes'],1):
 tagline,bio,color,beat=bios[e['id']];script=(DIR/e['script_file']).read_text()
 paragraphs=''.join('<p>'+h(x)+'</p>' for x in script.strip().split('\n\n'))
 sources=''.join('<li><a href="'+h(s['url'],quote=True)+'" target="_blank" rel="noopener noreferrer">'+h(s['title'])+' ↗</a><p>'+h(', '.join(s['authors']))+'</p><small>'+h(s['published']+' · '+s['license'])+('</small><p><a href="'+h(s['licenseURL'],quote=True)+'">Reuse terms ↗</a></p>' if s.get('licenseURL') else '</small>')+'</li>' for s in e['sources'])
 voice=e.get('voice') or {};name=voice.get('name','Voice selection pending')
 audio='<p class="pending">Narration pending provider access.</p>'
 if e.get('audio_file') and (DIR/e['audio_file']).exists():
  audio='<audio controls preload="metadata" aria-label="Listen to '+h(e['title'],quote=True)+'"><source src="'+h(e['audio_file'],quote=True)+'" type="audio/mpeg"></audio>'
 duration=e.get('duration_seconds');time=f'{int(duration)//60}:{int(duration)%60:02d}' if duration else '~3 min'
 cards.append(f'''<article id="{e['id']}" style="--accent:{color}">
<div class="art" aria-hidden="true"><div class="orbit one"></div><div class="orbit two"></div><div class="planet"></div><span class="number">0{number}</span><span class="beat">{beat}</span></div>
<div class="cardbody"><div class="eyebrow">{h(e['host'])} <span>{time}</span></div><h2>{h(e['title'])}</h2><p class="dek">{h(e['dek'])}</p>{audio}
<details><summary>Meet {h(e['host'].split()[0])}</summary><h3>{h(tagline)}</h3><p>{h(bio)}</p><p class="small">Fictional AI presenter · Voice: {h(name)}</p></details>
<details><summary>Read the episode</summary><div class="transcript">{paragraphs}</div><a class="download" href="{h(e['script_file'],quote=True)}" download>Download transcript ↓</a></details>
<details><summary>Follow the evidence</summary><ol class="sources">{sources}</ol><p class="small">Original Science Break adaptation; changes made. Research findings are paraphrased; source titles and author names are retained for attribution. No source images are reproduced.</p></details>
</div></article>''')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Science Break — Three ways to stay curious</title><style>
:root{color-scheme:light;--ink:#20231e;--paper:#f5f3eb;--muted:#66685f;--acid:#dceba5}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,-apple-system,sans-serif}a{color:inherit;text-underline-offset:4px}header,main,footer{max-width:1260px;margin:auto;padding:24px 32px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #deded1}.brand{font:700 48px Georgia,serif;letter-spacing:-3px}.edition{font:11px ui-monospace,monospace;letter-spacing:1.2px;text-align:right}h1{font:clamp(46px,6vw,76px)/1.04 Georgia,serif;letter-spacing:-2.5px;max-width:720px;margin:32px 0 18px}h2{font:30px/1.13 Georgia,serif;letter-spacing:-.7px;margin:16px 0}h3{font:23px/1.3 Georgia,serif}.intro{max-width:650px;color:var(--muted);font-size:18px}.chips{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0 36px}.chips a{background:var(--acid);padding:9px 15px;border-radius:40px;text-decoration:none;font-size:13px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));align-items:start;gap:22px}article{background:#fffdf7;border:1px solid #e5e4d9;border-radius:26px;overflow:hidden;scroll-margin-top:20px}.art{height:210px;position:relative;overflow:hidden;background:var(--accent)}.orbit{position:absolute;width:240px;height:120px;border:1px solid #20231e66;border-radius:50%;top:30px;left:50%;transform:translateX(-50%) rotate(-30deg)}.two{transform:translateX(-50%) rotate(45deg);height:190px;top:0}.planet{position:absolute;width:112px;height:112px;left:50%;top:38px;transform:translateX(-50%);border-radius:50%;background:radial-gradient(circle at 28% 24%,#f8f5dd,var(--accent) 50%,#383e4b 100%);box-shadow:10px 18px 30px #20231e22}.number{position:absolute;top:14px;left:18px;font:12px ui-monospace,monospace}.beat{position:absolute;bottom:17px;left:18px;font:10px ui-monospace,monospace;letter-spacing:1px}.cardbody{padding:24px}.eyebrow{font:11px ui-monospace,monospace;text-transform:uppercase;letter-spacing:.6px;display:flex;justify-content:space-between;gap:8px}.dek{color:var(--muted);font-size:14px;min-height:66px}audio{width:100%;height:44px;margin:6px 0 20px}details{border-top:1px solid #deded1;padding:14px 0}summary{cursor:pointer;font-weight:550;font-size:14px;min-height:28px}summary:focus-visible,a:focus-visible{outline:2px solid #20231e;outline-offset:4px}.transcript{font:18px/1.65 Georgia,serif}.small,small{font-size:12px;color:var(--muted)}.sources{padding-left:18px;font-size:13px}.sources li{padding:10px 0;overflow-wrap:anywhere}.sources p{margin:8px 0}.download{font-size:13px}.pending{border:1px dashed #bbb7a4;padding:12px;font-size:13px;border-radius:10px}footer{margin-top:28px;font-size:12px;color:var(--muted);border-top:1px solid #deded1}footer details{border:0}footer p{max-width:860px}@media(max-width:950px){.grid{grid-template-columns:1fr;max-width:660px;margin:auto}.art{height:210px}.dek{min-height:0}header,main,footer{padding:20px}.edition{font-size:9px}h1{letter-spacing:-1.5px}.cardbody{padding:22px}}
</style></head><body><header><div class="brand">lilt.</div><div class="edition">THE LISTENING ROOM<br>10—17 SEPTEMBER 2026</div></header><main><div class="eyebrow" style="margin-top:24px">THREE HOSTS. THREE FRESH DISCOVERIES.</div><h1>Big ideas.<br>Good company.</h1><p class="intro">A changing Moon. An unexpected meal. A tiny brain with a remarkable way of paying attention. Find your kind of curious.</p><nav class="chips" aria-label="Choose a host"><a href="#mira">Mira · Space</a><a href="#clara">Clara · Nature</a><a href="#elias">Elias · Neuroscience</a></nav><div class="grid">'''+''.join(cards)+'''</div></main><footer><p>Private listening preview · Fictional AI presenters · Synthetic narration · Original scripts with source attribution.</p><details><summary>Production notes</summary><p>Scripts were authored in this Codex session from retrieved evidence, not through the production Luna API. Narration uses Eleven Multilingual v2. Voice choices are current ElevenLabs recommendations; popularity rankings could not be checked with this key’s restricted read permissions. These samples are not published production episodes and still require independent editorial and listening approval.</p><p><a href="manifest.json">Source and casting manifest</a> · <a href="EVIDENCE.md">Evidence review</a> · <a href="../../docs/CHARACTERS.md">Character bible</a></p></details></footer><script>document.querySelectorAll('audio').forEach(a=>a.addEventListener('play',()=>document.querySelectorAll('audio').forEach(b=>{if(b!==a)b.pause()})));</script></body></html>'''
(DIR/'index.html').write_text(page)
print(DIR/'index.html')
